mapper.select:
select * from mem_config_sync_batch
where tenant_id = #{tenantId} and idempotency_key = #{idempotencyKey}
limit 1

select * from mem_config_sync_detail
where tenant_id = #{tenantId} and batch_id = #{batchId}
order by detail_id

mapper.update:
update mem_config_sync_detail
set decision = #{decision}
where tenant_id = #{tenantId} and batch_id = #{batchId} and detail_id = #{detailId}
  and result_status = 'PENDING'

update mem_config_sync_batch
set status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where tenant_id = #{tenantId} and batch_id = #{batchId}
